#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int u, v;
    long long w;
} Edge;

int cmp_edges(const void *a, const void *b) {
    long long wa = ((const Edge *)a)->w;
    long long wb = ((const Edge *)b)->w;
    if (wa < wb) return -1;
    if (wa > wb) return 1;
    return 0;
}

int find_set(int v, int *parent) {
    if (v == parent[v])
        return v;
    return parent[v] = find_set(parent[v], parent);
}

int main() {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int total_cells = n * m;
    long long *p = (long long *)malloc(total_cells * sizeof(long long));
    for (int i = 0; i < total_cells; i++) {
        scanf("%lld", &p[i]);
    }

    int max_edges = 2 * total_cells;
    Edge *edges = (Edge *)malloc(max_edges * sizeof(Edge));
    int edge_count = 0;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            int u = i * m + j;
            if (i + 1 < n) {
                int v = (i + 1) * m + j;
                long long w = p[u] > p[v] ? p[u] : p[v];
                edges[edge_count++] = (Edge){u, v, w};
            }
            if (j + 1 < m) {
                int v = i * m + (j + 1);
                long long w = p[u] > p[v] ? p[u] : p[v];
                edges[edge_count++] = (Edge){u, v, w};
            }
        }
    }

    qsort(edges, edge_count, sizeof(Edge), cmp_edges);

    int max_nodes = 2 * total_cells;
    int *dsu_parent = (int *)malloc(max_nodes * sizeof(int));
    for (int i = 0; i < max_nodes; i++) {
        dsu_parent[i] = i;
    }

    int *lc = (int *)malloc(max_nodes * sizeof(int));
    int *rc = (int *)malloc(max_nodes * sizeof(int));
    long long *weight = (long long *)malloc(max_nodes * sizeof(long long));
    long long *sum = (long long *)malloc(max_nodes * sizeof(long long));
    long long *ans = (long long *)malloc(max_nodes * sizeof(long long));

    for (int i = 0; i < total_cells; i++) {
        lc[i] = rc[i] = -1;
        weight[i] = 0;
        sum[i] = p[i];
    }

    int node_count = total_cells;
    for (int i = 0; i < edge_count; i++) {
        int root_u = find_set(edges[i].u, dsu_parent);
        int root_v = find_set(edges[i].v, dsu_parent);

        if (root_u != root_v) {
            int new_node = node_count++;
            lc[new_node] = root_u;
            rc[new_node] = root_v;
            weight[new_node] = edges[i].w;
            sum[new_node] = sum[root_u] + sum[root_v];

            dsu_parent[root_u] = new_node;
            dsu_parent[root_v] = new_node;
            dsu_parent[new_node] = new_node;
        }
    }

    int root = node_count - 1;
    ans[root] = sum[root];

    for (int i = node_count - 1; i >= total_cells; i--) {
        int left = lc[i];
        int right = rc[i];
        long long w = weight[i];

        if (sum[left] >= w) {
            ans[left] = ans[i];
        } else {
            ans[left] = sum[left];
        }

        if (sum[right] >= w) {
            ans[right] = ans[i];
        } else {
            ans[right] = sum[right];
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            int u = i * m + j;
            printf("%lld%c", ans[u], j == m - 1 ? '\n' : ' ');
        }
    }

    free(p);
    free(edges);
    free(dsu_parent);
    free(lc);
    free(rc);
    free(weight);
    free(sum);
    free(ans);

    return 0;
}
